insert into public.question_translations (question_id, dil, soru, secenekler)
select q.id, 'en', v.en_soru, v.en_secenekler
  from (values
  ('Whistler''ın ''Ressamın Annesi'' tablosunda kadın izleyiciye nasıl görünür?', 'How is the woman shown to the viewer in Whistler''s ''Arrangement in Grey and Black No. 1''?', '["In profile","From the front","From behind","From above"]'::jsonb),
